const msg = $input.first().json.message.text || '';
const cmd = msg.trim().toLowerCase();

// 명령어 파싱
let action = 'unknown';
let params = {};

if (cmd === '/현황' || cmd === '/status' || cmd.includes('현황') || cmd.includes('리드')) {
  action = 'status';
} else if (cmd === '/hot' || cmd.includes('핫') || cmd.includes('hot')) {
  action = 'hot_leads';
} else if (cmd === '/csv' || cmd.includes('csv') || cmd.includes('다운') || cmd.includes('엑셀')) {
  action = 'csv_download';
} else if (cmd === '/도움' || cmd === '/help' || cmd === '/start' || cmd.includes('도움')) {
  action = 'help';
} else if (cmd.startsWith('/사업부')) {
  action = 'by_unit';
  const unit = cmd.replace('/사업부', '').trim();
  if (unit.includes('a') || unit.includes('펜션') || unit.includes('달팽이')) params.unit = 'pension';
  else if (unit.includes('b') || unit.includes('공방') || unit.includes('스토리')) params.unit = 'cnc';
  else if (unit.includes('c') || unit.includes('자동화') || unit.includes('ai')) params.unit = 'automation';
  else if (unit.includes('d') || unit.includes('웹') || unit.includes('개발')) params.unit = 'webdev';
  else params.unit = 'all';
} else if (cmd === '/오늘' || cmd.includes('오늘')) {
  action = 'today';
} else if (cmd === '/이번주' || cmd.includes('이번주') || cmd.includes('주간')) {
  action = 'weekly';
} else if (cmd === '/검색' || cmd.startsWith('/검색 ')) {
  action = 'search';
  params.query = cmd.replace('/검색', '').trim();
} else {
  action = 'help';
}

return [{ json: { action, params, chatId: $input.first().json.message.chat.id } }];

const leads = $input.all().map(i => i.json);
const flat = Array.isArray(leads[0]) ? leads[0] : leads;

const units = { pension: '🏕️A-달팽이', cnc: '🔨B-스토리팜', automation: '🤖C-AI자동화', webdev: '💻D-웹개발' };
const byUnit = {};
const byStage = { cold: 0, warm: 0, hot: 0, customer: 0, fan: 0 };

flat.forEach(l => {
  byUnit[l.business_unit] = (byUnit[l.business_unit] || 0) + 1;
  if (l.stage) byStage[l.stage]++;
});

const total = flat.length;
const hotCount = flat.filter(l => l.score >= 50).length;

let msg = `📊 *가망고객 수집 현황*\n━━━━━━━━━━━━━━\n\n`;
msg += `📦 *총 리드: ${total}건*\n`;
msg += `🔥 Hot 리드: ${hotCount}건\n\n`;
msg += `🏢 *사업부별*\n`;
Object.entries(byUnit).forEach(([k, v]) => {
  msg += `  ${units[k] || k}: ${v}건\n`;
});
msg += `\n📊 *등급별*\n`;
msg += `  ❄️Cold: ${byStage.cold} | 🌡Warm: ${byStage.warm} | 🔥Hot: ${byStage.hot}\n`;
msg += `  ✅Customer: ${byStage.customer} | ⭐Fan: ${byStage.fan}\n`;
msg += `\n💡 /hot → Hot 리드 목록\n💡 /csv → CSV 다운로드\n💡 /오늘 → 오늘 수집분`;

return [{ json: { text: msg } }];

const leads = $input.all().map(i => i.json);
const flat = Array.isArray(leads[0]) ? leads[0] : leads;

const units = { pension: '🏕️', cnc: '🔨', automation: '🤖', webdev: '💻' };

if (flat.length === 0) {
  return [{ json: { text: '🔥 *Hot 리드 없음*\n\n아직 스코어 50점 이상 리드가 없습니다.\n크롤링이 더 돌아야 합니다!' } }];
}

let msg = `🔥 *Hot 리드 TOP ${Math.min(flat.length, 20)}*\n━━━━━━━━━━━━━━\n\n`;

flat.slice(0, 20).forEach((l, i) => {
  msg += `*${i+1}. ${l.name || '이름없음'}* ${units[l.business_unit] || ''} (${l.score}점)\n`;
  if (l.company) msg += `  🏢 ${l.company}\n`;
  if (l.phone) msg += `  📱 ${l.phone}\n`;
  if (l.email) msg += `  📧 ${l.email}\n`;
  if (l.need) msg += `  💡 ${l.need}\n`;
  msg += `\n`;
});

msg += `\n📞 *즉시 연락 필요!*`;

return [{ json: { text: msg } }];

const leads = $input.all().map(i => i.json);
const flat = Array.isArray(leads[0]) ? leads[0] : leads;

const units = { pension: 'A-달팽이아지트', cnc: 'B-스토리팜', automation: 'C-AI자동화', webdev: 'D-웹개발' };

// BOM for Excel Korean support
const BOM = '\uFEFF';
const headers = ['No','이름','전화번호','이메일','상호명','주소','사업부','출처','관심분야','니즈','등급','스코어','웹사이트','웹상태','수집일'];
let csv = BOM + headers.join(',') + '\n';

flat.forEach((l, i) => {
  const row = [
    i + 1,
    l.name || '',
    l.phone || '',
    l.email || '',
    l.company || '',
    l.address || '',
    units[l.business_unit] || l.business_unit || '',
    l.source || '',
    Array.isArray(l.interest) ? l.interest.join(';') : (l.interest || ''),
    l.need || '',
    l.grade || '',
    l.score || 0,
    l.website_url || '',
    l.website_status || '',
    l.created_at ? l.created_at.split('T')[0] : ''
  ].map(v => `"${String(v).replace(/"/g, '""')}"`);
  csv += row.join(',') + '\n';
});

// CSV를 바이너리로 변환
const buffer = Buffer.from(csv, 'utf-8');
const today = new Date().toISOString().split('T')[0];

return [{
  json: { total: flat.length, filename: `leads_${today}.csv` },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/csv',
      fileName: `가망고객_리드_${today}.csv`,
      fileExtension: 'csv'
    }
  }
}];

const leads = $input.all().map(i => i.json);
const flat = Array.isArray(leads[0]) ? leads[0] : leads;
const units = { pension: '🏕️', cnc: '🔨', automation: '🤖', webdev: '💻' };

if (flat.length === 0) {
  return [{ json: { text: '📅 *오늘 수집: 0건*\n\n아직 오늘 수집된 리드가 없습니다.' } }];
}

let msg = `📅 *오늘 수집 현황*\n━━━━━━━━━━━━━━\n\n`;
msg += `📦 총 ${flat.length}건 수집\n\n`;

flat.slice(0, 30).forEach((l, i) => {
  const icon = l.score >= 50 ? '🔥' : l.score >= 20 ? '🌡' : '❄️';
  msg += `${icon} *${l.name || l.company || '이름없음'}* ${units[l.business_unit]||''} (${l.score}점)\n`;
  if (l.phone) msg += `  📱 ${l.phone}\n`;
  if (l.need) msg += `  💡 ${l.need}\n`;
});

if (flat.length > 30) msg += `\n... 외 ${flat.length - 30}건`;

return [{ json: { text: msg } }];
